solution:
fn parse_age(input: Str) -> Option[Int] {
  let value = input.parse_int();
  return match value {
    Some(v) => if v >= 0 && v <= 150 { return Some(v); } else { return None(); },
    None => None(),
  };
}

fn main() -> Int {
  match parse_age("25") {
    Some(age) => return age,
    None => return 0,
  }
}
